#!/usr/bin/env sh
# Generate config.js from .env so the browser can read it.
# Usage: ./scripts/gen-config.sh
set -e
cd "$(dirname "$0")/.."

if [ ! -f .env ]; then
    echo "No .env found. Copy .env.example to .env and fill it in." >&2
    exit 1
fi

API_KEY=$(sed -n 's/^API_KEY=//p' .env | tr -d '"'"'"'\r')

cat > config.js <<CONFIG
// Generated by scripts/gen-config.sh from .env. Do not commit.
window.APP_CONFIG = {
    API_KEY: "$API_KEY"
};
CONFIG

echo "Wrote config.js"
